        private List<Tuple<Tuple<int, int>, char>> GetPathForLab(LabMap labmap)
        {
            var path = new List<Tuple<Tuple<int, int>, char>>();
            var currentDirection = 'N';
            var currentPosition = labmap.startingPosition;

            while (!currentDirection.Equals('X'))
            {
                var res = labmap.SimulateMove(currentPosition, currentDirection);
                //path.AddRange(res.Item1);
                foreach (var pos in res.Item1)
                {
                    path.Add(new Tuple<Tuple<int, int>, char>(pos, currentDirection));
                }

                currentDirection = res.Item2;
                currentPosition = res.Item1.Last();
            }

            return path.Distinct().ToList();
        }

        private bool CheckCircularityFromStartingPoint(Tuple<int, int> loopStartingPoint, char loopStartingDirection, LabMap map)
        {
            var currentPosition = map.startingPosition;
            var currentDirection = 'N';
            var maxTries = MAX_PATH_STEPS;
            var hitCount = 0;

            //dbg
            var path = new List<Tuple<int, int>>() { map.startingPosition };

            while (!currentDirection.Equals('X') && maxTries >= 0)
            {
                maxTries--;
                //Console.WriteLine($"\t>> ({currentPosition.Item1},{currentPosition.Item2}) [{currentDirection}] t={101 - maxTries}");
                var res = map.SimulateMove(currentPosition, currentDirection);

                //dbg
                path.AddRange(res.Item1);

                if (res.Item1.Count == 0)
                {
                    currentDirection = map.Turn(currentDirection);
                }
                else
                {
                    currentDirection = res.Item2;
                    currentPosition = res.Item1.Last();
                }

                // direction must be the turned direction, because SimulateMove gives the **after** direction
                if (currentPosition.Item1 == loopStartingPoint.Item1 && currentPosition.Item2 == loopStartingPoint.Item2 && currentDirection == map.Turn(loopStartingDirection))
                {
                    hitCount++;
                }

                if (hitCount > 1)
                {
                    return true;
                }
            }

            return false;
        }

        private bool CheckPathCircularity(List<Tuple<int, int>> path, Tuple<int, int> startingPoint, char direction)
        {
            // segment the path into so that each new elment starts with `startingPoint`
            var segments = new List<List<Tuple<int, int>>>();
            var indexes = Helper.FindAllIndex(path.ToArray(), pos => pos.Item1 == startingPoint.Item1 && pos.Item2 == startingPoint.Item2);

            for (var i = 0; i < indexes.Length - 1; i++)
            {
                segments.Add(path.GetRange(indexes[i], indexes[i + 1] - indexes[i]));
            }

            // TODO use path.ToList().SequenceEqual
            var allSegmentsEqual = true;
            for (var i = 0; i < segments.Count - 1; i++)
            {
                allSegmentsEqual &= segments[i].SequenceEqual(segments[i + 1]);
            }

            return allSegmentsEqual;
        }

    }


    internal static class Helper
    {
        public static int[] FindAllIndex<T>(this T[] array, Predicate<T> match)
        {
            return array.Select((value, index) => match(value) ? index : -1)
                    .Where(index => index != -1).ToArray();
        }
    }

    internal class LabMap
    {
        public List<string> lines { get; set; }
        public List<Tuple<int, int>> obstacles { get; set; }
        public Tuple<int, int> startingPosition { get; set; }

        private int mapWidth { get; set; }
        private int mapHeight { get; set; }

        public LabMap(string input)
        {
            // get the map lines
            lines = input.Replace("\r", "").Split('\n').ToList();

            // get map dimensions
            mapHeight = lines.Count;
            mapWidth = lines[0].Length;

            // get all obstacles
            obstacles = new List<Tuple<int, int>>();
            for (var i = 0; i < lines.Count; i++)
            {
                for (var j = 0; j < lines[i].Length; j++)
                {
                    if (lines[i][j].Equals('#'))
                    {
                        obstacles.Add(new Tuple<int, int>(i, j));
                    }
                    else if (lines[i][j].Equals('^'))
                    {     // get the starting position
                        startingPosition = new Tuple<int, int>(i, j);
                    }
                }
            }

        }

        private LabMap() { }

        public LabMap GenerateObstacleAtPosition(Tuple<int, int> obstaclePosition)
        {
            LabMap clone = new LabMap();
            clone.lines = this.lines;
            clone.obstacles = this.obstacles.Concat(new[] { obstaclePosition }).ToList();
            clone.startingPosition = this.startingPosition;
            clone.mapHeight = this.mapHeight;
            clone.mapWidth = this.mapWidth;

            return clone;
        }

        /// <summary>
        /// The guard path until the guard needs to turn
        /// </summary>
        /// <param name="startingPosition"></param> The positions that were traversed.
        /// <param name="direction"></param> The direction the Guard is looking at the last traversed position
        /// <returns></returns>
        public Tuple<List<Tuple<int, int>>, char> SimulateMove(Tuple<int, int> startingPosition, char direction)
        {
            var maxIterations = mapHeight * mapWidth;

            List<Tuple<int, int>> traversedPath = new List<Tuple<int, int>>();
            Tuple<int, int> nextPosition = startingPosition;
            while (maxIterations > 0)
            {
                maxIterations--;

                nextPosition = CalculateNextPosition(nextPosition, direction);

                // check if the position is an obstacle
                if (this.obstacles.Where(obstacle => obstacle.Equals(nextPosition)).Count() > 0)
                {
                    // position is an obstacle!
                    return new Tuple<List<Tuple<int, int>>, char>(traversedPath, Turn(direction));
                }

                // check if the position is outside of the map
                if (nextPosition.Item1 < 0 || nextPosition.Item1 >= this.mapHeight || nextPosition.Item2 < 0 || nextPosition.Item2 > this.mapWidth)
                {
                    // position is outside of map
                    return new Tuple<List<Tuple<int, int>>, char>(traversedPath, 'X');
                }

                // position is valid
                traversedPath.Add(nextPosition);
            }

            return null;
        }

        public Tuple<int, int> CalculateNextPosition(Tuple<int, int> startingPosition, char direction)
        {
            switch (direction)
            {
                case 'N': return new Tuple<int, int>(startingPosition.Item1 - 1, startingPosition.Item2);
                case 'E': return new Tuple<int, int>(startingPosition.Item1, startingPosition.Item2 + 1);
                case 'S': return new Tuple<int, int>(startingPosition.Item1 + 1, startingPosition.Item2);
                case 'W': return new Tuple<int, int>(startingPosition.Item1, startingPosition.Item2 - 1);
                case 'X':
                default:
                    // guard is off the map
                    return startingPosition;
            }
        }

        public char Turn(char direction)
        {
            switch (direction)
            {
                case 'N': return 'E';
                case 'E': return 'S';
                case 'S': return 'W';
                case 'W': return 'N';
                case 'X':
                default:
                    return 'X';
            }
        }

        public bool HasObstacleInTurnPath(Tuple<int, int> position, char direction)
        {
            var interestingX = new List<int>() { 6, 7, 8 };
            var interestingY = new List<int>() { 4, 6, 2, 8 };
            if (interestingX.Contains(position.Item1) && interestingY.Contains(position.Item2))
            {
                var hit = 1;
            }

            // check if there is an obstacle in you could turn into, if there were a obstacle in the next position of the current path
            var candidates = new List<Tuple<int, int>>();
            switch (direction)
            {
                case 'N':
                    // x=, y+
                    candidates = obstacles.Where(obstacle => obstacle.Item1 == position.Item1 && obstacle.Item2 > position.Item2).ToList();
                    break;
                case 'E':
                    // x-, y=
                    candidates = obstacles.Where(obstacle => obstacle.Item1 > position.Item1 && obstacle.Item2 == position.Item2).ToList();
                    break;
                case 'S':
                    // x=, y-
                    candidates = obstacles.Where(obstacle => obstacle.Item1 == position.Item1 && obstacle.Item2 < position.Item2).ToList();
                    break;
                case 'W':
                    // x+,y=
                    candidates = obstacles.Where(obstacle => obstacle.Item1 < position.Item1 && obstacle.Item2 == position.Item2).ToList();
                    break;
            }

            return candidates.Count > 0;
        }
    }
